INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is a ''bicomponent fiber'' (used in some spun-blend applications) structurally composed of?', '["Two different polymers (or the same polymer with different properties) combined within a single fiber cross-section, often to achieve self-crimping or special performance effects","A single homogeneous polymer with absolutely no internal structural variation","A fiber made from exactly two separate, physically twisted-together strands rather than one continuous filament","A fiber that always contains two different dye colors printed onto its surface"]'::jsonb, 'Two different polymers (or the same polymer with different properties) combined within a single fiber cross-section, often to achieve self-crimping or special performance effects', 'Bicomponent fibers combine two distinct polymer components (e.g., side-by-side or core-sheath arrangement) within a single filament''s cross-section; differing shrinkage/expansion behavior between the two components can create self-crimping or other special functional effects not achievable with a single homogeneous polymer.', 2, '{"bicomponent-fiber"}'::text[]);
